package com.queuex.api.service;
import com.queuex.api.model.Job; import com.queuex.api.repo.JobRepository; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class JobService { private final JobRepository repo; private final KafkaTemplate<String,String> kafka; public JobService(JobRepository r,KafkaTemplate<String,String> k){repo=r;kafka=k;}
 public Job create(UUID owner,String type,String payload,int priority,int max,Instant scheduled){Job j=new Job();j.ownerId=owner;j.jobType=type;j.payload=payload;j.priority=priority;j.maxAttempts=max;j.status="QUEUED";j.scheduledAt=scheduled==null?Instant.now():scheduled;return repo.save(j);}
 public List<Job> list(UUID owner){return repo.findTop100ByOwnerIdOrderByCreatedAtDesc(owner);} public Job get(UUID id,UUID owner){return repo.findByIdAndOwnerId(id,owner).orElseThrow(()->new NoSuchElementException("Job not found"));}
 public void cancel(UUID id,UUID owner){Job j=get(id,owner);if(List.of("QUEUED","RETRYING").contains(j.status)){j.status="CANCELLED";j.updatedAt=Instant.now();repo.save(j);}}
 public Job retry(UUID id,UUID owner){Job j=get(id,owner);if(!List.of("DEAD","FAILED","CANCELLED").contains(j.status))throw new IllegalStateException("Only dead/failed/cancelled jobs can be retried");j.status="QUEUED";j.attempts=0;j.lastError=null;j.finishedAt=null;j.scheduledAt=Instant.now();j.updatedAt=Instant.now();return repo.save(j);}
 @Scheduled(fixedDelayString="${app.dispatch-delay-ms:3000}") @Transactional public void dispatch(){repo.findAll().stream().filter(j->"QUEUED".equals(j.status)&&!j.scheduledAt.isAfter(Instant.now())).sorted(Comparator.comparingInt((Job j)->j.priority).reversed()).limit(100).forEach(j->{kafka.send("queuex.jobs",j.id.toString(),j.id.toString());});}
}
